class E(Exception):
 def __repr__(self): return "OVERRIDE"
 def __str__(self): return "OVERRIDE"
 def __init__(self, *args): events.append("init")
 def __setattr__(self, name, value):
  events.append(("set", name, value))
  object.__setattr__(self, name, value)
 def add_note(self, note): events.append("note")
 def with_traceback(self, tb): events.append("traceback")
e=E("original")
try:
 result=BaseException.__repr__(e)
except BaseException as error:
 result=(type(error).__name__, str(error), error.args)
result=(result, events)

